mapper.select:
SELECT cs.*, s.student_no, u.real_name as student_name, c.course_name, u2.real_name as teacher_name FROM course_selections cs LEFT JOIN students s ON cs.student_id = s.id LEFT JOIN users u ON s.user_id = u.id LEFT JOIN courses c ON cs.course_id = c.id LEFT JOIN teachers t ON cs.teacher_id = t.id LEFT JOIN users u2 ON t.user_id = u2.id
AND s.student_no LIKE CONCAT("%", #{studentNo}, "%")
AND cs.course_id = #{courseId}
AND cs.semester = #{semester}
LIMIT #{offset}, #{limit}

SELECT COUNT(*)
FROM course_selections cs
LEFT JOIN students s ON cs.student_id = s.id


        AND s.student_no LIKE CONCAT("%", #{studentNo}, "%")


        AND cs.course_id = #{courseId}


        AND cs.semester = #{semester}
